#!/usr/bin/env node
// PreToolUse: Edit|Write — blocks direct edits to .env files and
// lockfiles. Lockfiles should be regenerated by the real package manager
// (npm install / cargo build), never hand-edited.

const path = require("path");

const PROTECTED = [
  /^\.env(\..*)?$/,
  /^package-lock\.json$/,
  /^pnpm-lock\.yaml$/,
  /^Cargo\.lock$/,
];

function main() {
  let raw = "";
  try {
    raw = require("fs").readFileSync(0, "utf8");
  } catch {
    process.exit(0);
  }

  let payload;
  try {
    payload = JSON.parse(raw);
  } catch {
    process.exit(0);
  }

  try {
    if (payload.tool_name !== "Edit" && payload.tool_name !== "Write") process.exit(0);
    const filePath = String(payload.tool_input && payload.tool_input.file_path || "");
    if (!filePath) process.exit(0);
    if (process.env.ALLOW_PROTECTED_EDIT === "1") process.exit(0);

    const base = path.basename(filePath);
    if (PROTECTED.some((re) => re.test(base))) {
      process.stderr.write(
        `Blocked: "${filePath}" is a protected file (secret store or lockfile).\n` +
        `Regenerate lockfiles via the real tool (npm install / cargo build), don't ` +
        `hand-edit them. Set ALLOW_PROTECTED_EDIT=1 to override.\n`
      );
      process.exit(2);
    }
    process.exit(0);
  } catch (err) {
    process.stderr.write(`guard-protected-files.cjs internal error (failing open): ${err}\n`);
    process.exit(0);
  }
}

main();
